package cn.course.antifraud;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.math.*;
import static cn.course.antifraud.Support.*;

@Service
public class Admin {
 private final Support s;private final Clues clues;
 public Admin(Support s,Clues clues){this.s=s;this.clues=clues;}
 public Map<String,Object> meta(User u){Map<String,Object> out=map("orgs",s.rows("SELECT * FROM af_org ORDER BY id"),"communities",s.rows("SELECT * FROM af_community ORDER BY id"));if(u.role().equals("CENTER")){out.put("victims",s.rows("SELECT id,name_enc,community_id FROM af_victim ORDER BY id").stream().peek(v->v.put("name",s.decrypt(v.remove("name_enc")))).toList());out.put("gridUsers",s.rows("SELECT id,display_name,community_id FROM af_user WHERE role='GRID' AND enabled=TRUE"));out.put("config",clues.config());}if(Set.of("CENTER","PAYMENT").contains(u.role()))out.put("banks",banks(u));return out;}
 public List<Map<String,Object>> banks(User u){u.roles("CENTER","PAYMENT");return s.rows("SELECT b.*,o.name org_name FROM af_bank b JOIN af_org o ON o.id=b.org_id"+(u.role().equals("PAYMENT")?" WHERE b.org_id=?":"")+" ORDER BY b.id",u.role().equals("PAYMENT")?new Object[]{u.orgId()}:new Object[]{}).stream().peek(b->{b.put("account",mask(s.decrypt(b.remove("number_enc"))));b.put("holder",s.decrypt(b.remove("holder_enc")));b.remove("number_hash");}).toList();}
 public List<Map<String,Object>> users(User u){u.administrator();return s.rows("SELECT id,username,display_name,role,org_id,community_id,victim_id,verified,enabled,admin FROM af_user ORDER BY id");}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public long user(User u,long id,Map<String,Object> b){u.administrator();String username=required(b,"username",60),display=required(b,"displayName",80),role=required(b,"role",20);require(Set.of("CENTER","PUBLIC","PAYMENT","GRID").contains(role),"角色无效");long org=num(b,"orgId"),community=num(b,"communityId"),victim=num(b,"victimId");boolean enabled=yes(b,"enabled"),verified=yes(b,"verified"),admin=yes(b,"admin")&&role.equals("CENTER");if(role.equals("PAYMENT"))s.one("SELECT id FROM af_org WHERE id=?",org);if(role.equals("GRID"))s.one("SELECT id FROM af_community WHERE id=?",community);if(verified){require(role.equals("PUBLIC")&&victim>0,"演示实名需要群众角色及已核验受害人");s.one("SELECT id FROM af_victim WHERE id=? FOR UPDATE",victim);if(enabled)conflict(s.count("SELECT COUNT(*) FROM af_user WHERE role='PUBLIC' AND enabled=TRUE AND verified=TRUE AND victim_id=? AND id<>?",victim,id)==0,"该受害人已有关联的核验账号，请先解除原账号关联");}else require(!role.equals("PUBLIC")||victim==0,"未核验账号不能关联受害人资料");if(id==u.id())require(enabled&&admin&&role.equals("CENTER"),"当前管理员不能停用自己或移除自己的权限");
  String password=str(b,"password");if(id==0||!password.isEmpty())require(password.length()>=8&&password.length()<=100,"密码长度应为8至100位");
  if(id==0)id=s.insert("INSERT INTO af_user(username,password_hash,display_name,role,org_id,community_id,victim_id,enabled,verified,admin) VALUES(?,?,?,?,?,?,?,?,?,?)",username,password(password),display,role,role.equals("PAYMENT")?org:null,role.equals("GRID")?community:null,role.equals("PUBLIC")&&victim>0?victim:null,enabled,verified,admin);
  else{s.one("SELECT id FROM af_user WHERE id=? FOR UPDATE",id);s.db.update("UPDATE af_user SET username=?,display_name=?,role=?,org_id=?,community_id=?,victim_id=?,enabled=?,verified=?,admin=? WHERE id=?",username,display,role,role.equals("PAYMENT")?org:null,role.equals("GRID")?community:null,role.equals("PUBLIC")&&victim>0?victim:null,enabled,verified,admin,id);if(!password.isEmpty())s.db.update("UPDATE af_user SET password_hash=? WHERE id=?",password(password),id);}
  s.log(u,"维护账号","account",id,null,enabled?"启用":"停用","账号及归属更新");return id;
 }
 public List<Map<String,Object>> blacklist(User u){u.roles("CENTER");return s.rows("SELECT id,kind,value_enc,source,enabled FROM af_blacklist ORDER BY id DESC LIMIT 300").stream().peek(r->r.put("value",s.decrypt(r.remove("value_enc")))).toList();}
 @Transactional public long blacklist(User u,long id,Map<String,Object> b){u.administrator();String kind=required(b,"kind",20),value=required(b,"value",500),source=required(b,"source",200);String normalized=Rules.normalize(kind,value);if(id==0)id=s.insert("INSERT INTO af_blacklist(kind,value_hash,value_enc,source,enabled) VALUES(?,?,?,?,?)",kind,s.fingerprint(kind,normalized),s.encrypt(value),source,yes(b,"enabled"));else{s.one("SELECT id FROM af_blacklist WHERE id=? FOR UPDATE",id);s.db.update("UPDATE af_blacklist SET kind=?,value_hash=?,value_enc=?,source=?,enabled=? WHERE id=?",kind,s.fingerprint(kind,normalized),s.encrypt(value),source,yes(b,"enabled"),id);}s.db.update("UPDATE af_rule_state SET blacklist_version=blacklist_version+1 WHERE id=1");s.log(u,"维护黑名单","blacklist",id,null,yes(b,"enabled")?"启用":"停用",source);return id;}
 public List<Map<String,Object>> configurations(User u){u.roles("CENTER");return s.rows("SELECT c.*,u.display_name FROM af_config c LEFT JOIN af_user u ON u.id=c.author_id ORDER BY c.id DESC").stream().peek(c->c.put("data",s.decode(str(c,"data")))).toList();}
 @Transactional public void configure(User u,Map<String,Object> b){u.administrator();Map<String,Object> c=new LinkedHashMap<>();for(String k:Rules.defaults().keySet())c.put(k,b.get(k));Rules.validateConfig(c);s.db.update("INSERT INTO af_config(data,author_id) VALUES(?,?)",s.encode(c),u.id());s.log(u,"发布配置","config",0,null,null,"发布新版本，旧评分和生效时限保持原值");}
 public List<Map<String,Object>> logs(User u){u.roles("CENTER");return s.rows("SELECT l.*,COALESCE(u.display_name,'系统') actor FROM af_log l LEFT JOIN af_user u ON u.id=l.actor_id ORDER BY l.id DESC LIMIT 300");}
 private String scope(User u,String alias){return switch(u.role()){case "PAYMENT"->" AND "+alias+".org_id="+u.orgId();case "GRID"->" AND "+alias+".community_id="+u.communityId();case "PUBLIC"->" AND "+alias+".owner_id="+u.id();default->"";};}
 public Map<String,Object> stats(User u,String from,String to){LocalDate start=from==null||from.isBlank()?LocalDate.now().minusDays(30):LocalDate.parse(from),end=to==null||to.isBlank()?LocalDate.now():LocalDate.parse(to);require(!end.isBefore(start)&&start.plusYears(5).isAfter(end),"请选择五年内的有效日期范围");LocalDateTime a=start.atStartOfDay(),z=end.plusDays(1).atStartOfDay();List<Map<String,Object>> metrics=new ArrayList<>();List<Map<String,Object>> risks=List.of(),daily;String role=u.role();
  if(role.equals("CENTER")||role.equals("PUBLIC")){String condition="created_at>=? AND created_at<?"+scope(u,"r");long reports=s.count("SELECT COUNT(*) FROM af_report r WHERE "+condition,a,z);metrics.add(map("label",role.equals("PUBLIC")?"我的举报":"受理线索","value",reports,"unit","条","tone","blue"));if(role.equals("CENTER")){long open=s.count("SELECT COUNT(*) FROM af_alert WHERE state NOT IN ('已闭环','已驳回','已作废') AND root_time>=? AND root_time<?",a,z);metrics.add(map("label","待协同处置","value",open,"unit","件","tone","orange"));risks=s.rows("SELECT level label,COUNT(*) value FROM af_alert WHERE root_time>=? AND root_time<? GROUP BY level",a,z);}else{metrics.add(map("label","我的申请","value",s.count("SELECT COUNT(*) FROM af_application r WHERE "+condition,a,z),"unit","件","tone","orange"));}daily=s.rows("SELECT DATE_FORMAT(created_at,'%Y-%m-%d') day,COUNT(*) value FROM af_report r WHERE "+condition+" GROUP BY DATE_FORMAT(created_at,'%Y-%m-%d') ORDER BY MIN(created_at)",a,z);}
  else if(role.equals("PAYMENT")){metrics.add(map("label","机构指令","value",s.count("SELECT COUNT(*) FROM af_command c WHERE created_at>=? AND created_at<?"+scope(u,"c"),a,z),"unit","条","tone","blue"));metrics.add(map("label","待处理指令","value",s.count("SELECT COUNT(*) FROM af_command c WHERE state IN ('已送达','受理中') AND created_at>=? AND created_at<?"+scope(u,"c"),a,z),"unit","条","tone","orange"));daily=s.rows("SELECT DATE_FORMAT(created_at,'%Y-%m-%d') day,COUNT(*) value FROM af_command c WHERE created_at>=? AND created_at<?"+scope(u,"c")+" GROUP BY DATE_FORMAT(created_at,'%Y-%m-%d') ORDER BY MIN(created_at)",a,z);}
  else{long total=s.count("SELECT COUNT(*) FROM af_visit v WHERE created_at>=? AND created_at<?"+scope(u,"v"),a,z),returned=s.count("SELECT COUNT(*) FROM af_visit v WHERE state IN ('已回传','已归档') AND created_at>=? AND created_at<?"+scope(u,"v"),a,z),success=s.count("SELECT COUNT(*) FROM af_visit v WHERE result='已完成' AND created_at>=? AND created_at<?"+scope(u,"v"),a,z);metrics.add(map("label","社区派发任务","value",total,"unit","件","tone","blue"));metrics.add(map("label","回传率","value",total==0?"—":BigDecimal.valueOf(returned*100.0/total).setScale(1,RoundingMode.HALF_UP),"unit",total==0?"":"%","tone","teal"));metrics.add(map("label","劝阻成功率","value",returned==0?"—":BigDecimal.valueOf(success*100.0/returned).setScale(1,RoundingMode.HALF_UP),"unit",returned==0?"":"%","tone","blue"));daily=s.rows("SELECT DATE_FORMAT(created_at,'%Y-%m-%d') day,COUNT(*) value FROM af_visit v WHERE created_at>=? AND created_at<?"+scope(u,"v")+" GROUP BY DATE_FORMAT(created_at,'%Y-%m-%d') ORDER BY MIN(created_at)",a,z);}
  if(role.equals("CENTER")||role.equals("PAYMENT")){var money=s.one("SELECT COALESCE(SUM(actual),0) frozen,COALESCE(SUM(returned),0) returned,COALESCE(SUM(remaining),0) remaining FROM af_command c WHERE kind='止付' AND created_at>=? AND created_at<?"+scope(u,"c"),a,z);metrics.add(map("label","实际冻结累计","value",money.get("frozen"),"unit","元","tone","teal"));metrics.add(map("label","成功返还累计","value",money.get("returned"),"unit","元","tone","teal"));metrics.add(map("label","当前剩余冻结","value",money.get("remaining"),"unit","元","tone","blue"));}
  if(role.equals("CENTER")||role.equals("GRID")){long people=s.count("SELECT COALESCE(SUM(r.people),0) FROM af_campaign_record r JOIN af_campaign c ON c.id=r.campaign_id WHERE r.occurred_at>=? AND r.occurred_at<?"+(role.equals("GRID")?" AND c.community_id="+u.communityId():""),a,z);metrics.add(map("label","宣传触达人次","value",people,"unit","人次","tone","blue"));}
  if(role.equals("CENTER")){long vt=s.count("SELECT COUNT(*) FROM af_visit WHERE created_at>=? AND created_at<?",a,z),vr=s.count("SELECT COUNT(*) FROM af_visit WHERE state IN ('已回传','已归档') AND created_at>=? AND created_at<?",a,z),vs=s.count("SELECT COUNT(*) FROM af_visit WHERE result='已完成' AND created_at>=? AND created_at<?",a,z);metrics.add(map("label","任务回传率","value",vt==0?"—":BigDecimal.valueOf(vr*100.0/vt).setScale(1,RoundingMode.HALF_UP),"unit",vt==0?"":"%","tone","blue"));metrics.add(map("label","劝阻成功率","value",vr==0?"—":BigDecimal.valueOf(vs*100.0/vr).setScale(1,RoundingMode.HALF_UP),"unit",vr==0?"":"%","tone","teal"));}
  List<Map<String,Object>> byKind=List.of(),byResult=List.of();
  if(Set.of("CENTER","PAYMENT").contains(role)){byKind=s.rows("SELECT c.kind label,COUNT(*) value,COALESCE(SUM(c.requested),0) requested,COALESCE(SUM(c.actual),0) actual FROM af_command c WHERE c.created_at>=? AND c.created_at<?"+scope(u,"c")+" GROUP BY c.kind",a,z);byResult=s.rows("SELECT r.result label,COUNT(*) value FROM af_receipt r JOIN af_command c ON c.id=r.command_id WHERE r.valid=TRUE AND c.created_at>=? AND c.created_at<?"+scope(u,"c")+" GROUP BY r.result",a,z);}
  return map("byKind",byKind,"byResult",byResult,"metrics",metrics,"risks",risks,"daily",daily,"from",start,"to",end,"asOf",s.now());
 }
}
